$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$poseType=$assembly.GetType('HalconWinFormsDemo.Models.VmPose2D',$true);$matchType=$assembly.GetType('HalconWinFormsDemo.Models.ShapeMatchResult',$true);$recipeType=$assembly.GetType('HalconWinFormsDemo.Models.VisionRecipe',$true);$roiType=$assembly.GetType('HalconWinFormsDemo.Models.RoiData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s64-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 180
function F([string]$name){$value=$main.GetField($name,$all).GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$parameters=@()){try{$main.GetMethod($name,$private).Invoke($window,$parameters)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw($name+': '+$e.Message)}}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){M 'CreateFlowTool' ([object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);$found=$tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args);@($found,$args[1])}
function Pose([double]$row,[double]$column,[double]$angle,[string]$context='Global.Image'){ $poseType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($row,$column,$angle,$context)) }
try{
  # A line: port data is discoverable inside the existing on-demand monitor, not another permanent toolbar command.
  Assert(-not(F 'PortDataMonitorExpander').IsExpanded) 'Port data monitor is not collapsed by default';Assert((F 'FlowDebugMonitorBorder').Visibility.ToString()-eq'Collapsed') 'Debug monitor occupies the default first screen';Assert((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S64 added a permanent top command';Assert((F 'PortDataMonitorGrid')-ne$null) 'Port data table is missing'

  # Typed contract and metadata: Shape.Pose2D -> PositionCorrection2D.Pose2D while the old triplet remains present.
  $shapeKind=Kind ShapeMatch;$correctionKind=Kind PositionCorrection2D;$shapeOutputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($shapeKind));$correctionInputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($correctionKind));Assert(($shapeOutputs|Where-Object{$_.PortName-eq'Pose2D'-and$_.DataType-eq'Pose2D'}).Count-eq1) 'Shape Pose2D output is missing';Assert(($correctionInputs|Where-Object{$_.PortName-eq'Pose2D'-and$_.DataType-eq'Pose2D'}).Count-eq1) 'Correction Pose2D input is missing';foreach($port in @('CurrentRow','CurrentColumn','CurrentAngle')){Assert(($correctionInputs|Where-Object{$_.PortName-eq$port-and$_.DataType-eq'Number'}).Count-eq1)('Legacy input missing: '+$port)}
  $pose=Pose 110 220 15 'FixtureCamera.Image';Assert([string]::IsNullOrEmpty($pose.GetValidationError())) 'Valid Pose2D was rejected';$clone=$pose.Clone();Assert(-not[object]::ReferenceEquals($pose,$clone)-and$clone.ToDisplayString()-eq$pose.ToDisplayString()) 'Pose2D clone/display is not deterministic';$serializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($poseType);$stream=New-Object IO.MemoryStream;try{$serializer.WriteObject($stream,$pose);$stream.Position=0;$roundPose=$serializer.ReadObject($stream)}finally{$stream.Dispose()};Assert($roundPose.Row-eq110-and$roundPose.Column-eq220-and$roundPose.AngleDegrees-eq15-and$roundPose.CoordinateContextId-eq'FixtureCamera.Image') 'Pose2D JSON roundtrip failed'

  # Publish the best Shape candidate through the real S63 publication path and consume it through the real HALCON correction tool.
  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$shape=Tool ShapeMatch 'Shape Locator';$correction=Tool PositionCorrection2D 'Pose Correction';$blob=Tool Blob 'Following Inspection';$flow.Add($shape);$flow.Add($correction);$flow.Add($blob)
  $matches=F 'shapeToolMatches';$listType=[Collections.Generic.List``1].MakeGenericType($matchType);$list=[Activator]::CreateInstance($listType);$match=[Activator]::CreateInstance($matchType);$match.Index=1;$match.Row=110;$match.Column=220;$match.AngleDeg=15;$match.Score=.93;$match.Scale=1.0;$list.Add($match);$matches[$shape.ToolId]=$list;$shape.ClearRuntimeOutputs();M 'PublishShapeMatchOutputs' ([object[]]@($shape,$null))|Out-Null;$shape.ResultCode='OK';$shape.RunStatus='完成';$shapePose=(Out $shape Pose2D)[1];Assert($shapePose.Row-eq110-and$shapePose.CoordinateContext-eq'ImagePixel') 'Shape did not publish the best typed pose'
  $correction.SetInputBinding('Pose2D',$shape.ToolId,'Pose2D');$correction.Parameters.PositionCorrectionReferenceRow=100;$correction.Parameters.PositionCorrectionReferenceColumn=200;$correction.Parameters.PositionCorrectionReferenceAngleDegrees=15;$record=M 'ExecuteFlowTool' ([object[]]@($correction,'S64 Pose2D'));Assert($record.ResultCode-eq'OK') 'Pose2D correction execution failed';Assert([Math]::Abs([double](Out $correction DeltaRow)[1]-10)-lt1e-9-and[Math]::Abs([double](Out $correction DeltaColumn)[1]-20)-lt1e-9) 'Pose2D correction delta is wrong';Assert((M 'BuildPositionCorrectionInputSummary' ([object[]]@($correction)))-match'Pose2D.*Shape Locator') 'Typed input summary is missing'

  # The typed correction still drives actual ROI/mask following.
  $blob.Parameters.PositionCorrectionToolId=$correction.ToolId;$detectionGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]0,[double]0,[double]19,[double]19));$maskGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]5,[double]5,[double]9,[double]9));$detection=M 'AddRoiLayer' ([object[]]@($detectionGeometry,'Typed Pose Detection',$blob));$mask=M 'AddRoiLayer' ([object[]]@($maskGeometry,'Typed Pose Mask',$blob));$detectionGeometry.Dispose();$maskGeometry.Dispose();$mask.IsMask=$true;$region=M 'CreateBoundRoiRegion' ([object[]]@($blob,$true));try{$area=$null;$row=$null;$column=$null;[HalconDotNet.HOperatorSet]::AreaCenter($region,[ref]$area,[ref]$row,[ref]$column);Assert([Math]::Abs([double](($area.ToDArr()|Measure-Object -Sum).Sum)-375)-lt.001) 'Typed pose ROI/mask following area is wrong';Assert([Math]::Abs($row.D-19.6666666667)-lt.01-and[Math]::Abs($column.D-29.6666666667)-lt.01) 'Typed pose did not move ROI/mask'}finally{$region.Dispose()}

  # The existing monitor traces the selected Pose2D connection, current value/context/cycle and pinned state.
  $connectionKey=($shape.ToolId,'Pose2D',$correction.ToolId,'Pose2D'-join'|');$main.GetField('selectedFlowConnectionKey',$private).SetValue($window,$connectionKey);(F 'FlowToolList').SelectedItem=$correction;(F 'DebugMonitorToolComboBox').SelectedItem=$correction;M 'RefreshFlowPortVisualization'|Out-Null;M 'RefreshFlowDebugMonitor'|Out-Null;$rows=F 'portDataMonitorRows';$poseRows=@($rows|Where-Object{$_.DataType-eq'Pose2D'});Assert($poseRows.Count-ge2) 'Selected connection did not expose both Pose2D endpoints';Assert(($poseRows|Where-Object{$_.StateKey-eq'Valid'-and$_.ValueText-match'R=110'-and$_.ContextText-match'ImagePixel'}).Count-ge2) 'Pose2D monitor value/context/state is wrong';Assert(($poseRows|Where-Object{$_.CycleText-match'^#'}).Count-ge1) 'Result cycle is missing from the port monitor'
  $pins=F 'pinnedPortMonitorKeys';$pins.Add($poseRows[0].MonitorKey)|Out-Null;M 'RefreshPortDataMonitorS64' ([object[]]@($correction))|Out-Null;Assert((F 'portDataMonitorRows'|Where-Object{$_.IsPinned}).Count-ge1) 'Pinned port was not retained'

  # Conflict, stale/not-run, invalid coordinate context and non-finite payloads are rejected explicitly.
  $correction.SetInputBinding('CurrentRow',$shape.ToolId,'Row');$failed=$false;try{M 'ExecuteFlowTool' ([object[]]@($correction,'S64 conflict'))|Out-Null}catch{$failed=$_.Exception.Message-match'不能同时连接'};Assert($failed) 'Pose2D and legacy input conflict was accepted';$correction.RemoveInputBinding('CurrentRow')
  $bad=Pose 110 220 15 'Robot.Base';$bad.CoordinateContext='Robot';$shape.SetOutputValue('Pose2D',$bad);$shape.ResultCode='OK';$failed=$false;try{M 'ExecuteFlowTool' ([object[]]@($correction,'S64 context'))|Out-Null}catch{$failed=$_.Exception.Message-match'坐标上下文'};Assert($failed) 'Non-image Pose2D context was accepted'
  $bad=Pose ([double]::NaN) 220 15 'FixtureCamera.Image';$shape.SetOutputValue('Pose2D',$bad);$shape.ResultCode='OK';$failed=$false;try{M 'ExecuteFlowTool' ([object[]]@($correction,'S64 NaN'))|Out-Null}catch{$failed=$_.Exception.Message-match'有限数值'};Assert($failed) 'Non-finite Pose2D was accepted';$shape.SetOutputValue('Pose2D',(Pose 110 220 15 'FixtureCamera.Image'));$shape.ResultCode='--';$failed=$false;try{M 'ExecuteFlowTool' ([object[]]@($correction,'S64 stale'))|Out-Null}catch{$failed=$_.Exception.Message-match'本周期 OK'};Assert($failed) 'Not-run/stale Pose2D source was accepted'

  # Legacy Number triplet stays executable.
  $rowTool=Tool NumericCalculation 'Legacy Row';$columnTool=Tool NumericCalculation 'Legacy Column';$angleTool=Tool NumericCalculation 'Legacy Angle';$legacy=Tool PositionCorrection2D 'Legacy Correction';foreach($tool in @($rowTool,$columnTool,$angleTool,$legacy)){$flow.Add($tool)};$rowTool.SetOutputValue('Number',[double]3);$columnTool.SetOutputValue('Number',[double]4);$angleTool.SetOutputValue('Number',[double]5);foreach($tool in @($rowTool,$columnTool,$angleTool)){$tool.ResultCode='OK'};$legacy.SetInputBinding('CurrentRow',$rowTool.ToolId,'Number');$legacy.SetInputBinding('CurrentColumn',$columnTool.ToolId,'Number');$legacy.SetInputBinding('CurrentAngle',$angleTool.ToolId,'Number');Assert((M 'ExecuteFlowTool' ([object[]]@($legacy,'S64 legacy'))).ResultCode-eq'OK') 'Legacy three-Number chain regressed'

  # Recipe, copy/remap, undo/redo and invalidation keep the typed connection real.
  $shape.ResultCode='OK';$shape.SetOutputValue('Pose2D',(Pose 110 220 15 'FixtureCamera.Image'));$correctionId=$correction.ToolId;$shapeId=$shape.ToolId;$recipe=M 'CaptureRecipe';$recipeSerializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($recipeType);$stream=New-Object IO.MemoryStream;try{$recipeSerializer.WriteObject($stream,$recipe);$stream.Position=0;$round=$recipeSerializer.ReadObject($stream)}finally{$stream.Dispose()};$saved=$round.ToolFlow|Where-Object{$_.ToolId-eq$correctionId}|Select-Object -First 1;Assert(($saved.InputBindings|Where-Object{$_.TargetPortName-eq'Pose2D'-and$_.SourceToolId-eq$shapeId-and$_.SourcePortName-eq'Pose2D'}).Count-eq1) 'Recipe lost Pose2D binding'
  $main.GetField('selectedFlowPortToolId',$private).SetValue($window,$correction.ToolId);$main.GetField('selectedFlowPortName',$private).SetValue($window,'Pose2D');$main.GetField('selectedFlowPortDirection',$private).SetValue($window,'IN');M 'ClearFlowPortSourceButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;Assert($null-eq$correction.GetInputBinding('Pose2D')) 'Pose2D binding did not clear';M 'UndoFlowEditButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;$correction=$flow|Where-Object{$_.ToolId-eq$correctionId}|Select-Object -First 1;Assert($null-ne$correction.GetInputBinding('Pose2D')) 'Undo did not restore Pose2D binding';M 'RedoFlowEditButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;$correction=$flow|Where-Object{$_.ToolId-eq$correctionId}|Select-Object -First 1;Assert($null-eq$correction.GetInputBinding('Pose2D')) 'Redo did not clear Pose2D binding';M 'UndoFlowEditButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;$correction=$flow|Where-Object{$_.ToolId-eq$correctionId}|Select-Object -First 1
  (F 'FlowToolList').SelectedItems.Clear();(F 'FlowToolList').SelectedItems.Add(($flow|Where-Object{$_.ToolId-eq$shapeId}|Select-Object -First 1));(F 'FlowToolList').SelectedItems.Add($correction);Assert([int](M 'CopySelectedFlowToolsToClipboard')-eq2) 'Pose2D block copy failed';Assert([int](M 'PasteFlowToolClipboard' ([object[]]@($flow.Count)))-eq2) 'Pose2D block paste failed';$copies=@($flow|Select-Object -Last 2);$copyShape=$copies|Where-Object{$_.Kind.ToString()-eq'ShapeMatch'}|Select-Object -First 1;$copyCorrection=$copies|Where-Object{$_.Kind.ToString()-eq'PositionCorrection2D'}|Select-Object -First 1;Assert($copyCorrection.GetInputBinding('Pose2D').SourceToolId-eq$copyShape.ToolId) 'Pose2D block copy did not remap source ToolId'
  $shape=($flow|Where-Object{$_.ToolId-eq$shapeId}|Select-Object -First 1).PSObject.BaseObject;$correction=($flow|Where-Object{$_.ToolId-eq$correctionId}|Select-Object -First 1).PSObject.BaseObject;$correction.SetOutputValue('DeltaRow',[double]10);$correction.ResultCode='OK';M 'InvalidateDownstreamResults' ([object[]]@($shape,'S64 upstream rerun'))|Out-Null;Assert($correction.ResultCode-eq'--'-and-not(Out $correction DeltaRow)[0]) 'Upstream invalidation retained stale correction output';M 'RefreshPortDataMonitorS64' ([object[]]@($correction))|Out-Null;Assert((F 'portDataMonitorRows'|Where-Object{$_.DataType-eq'Pose2D'-and$_.StateKey-eq'Stale'}).Count-eq0) 'Monitor retained a stale Pose2D after invalidation'
  Write-Output 'S64 default-collapsed VM port data monitor + pinned/selected trace + typed Pose2D Shape chain + HALCON correction/ROI following + legacy/recipe/copy/undo/redo/failure/invalidation passed'
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
